import { sql } from "drizzle-orm";
import {
  bigint,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

import { user } from "./schema";

/**
 * What an account is *for*: everything a signed-in visitor saves.
 *
 * **This file is hand-written, and that is the point.** `lib/db/schema.ts` is
 * generated by the Better Auth CLI and `npm run db:schema` overwrites it, so a
 * table added there would vanish the next time anyone regenerates the auth
 * schema — silently, because the generator has no idea it was not the only
 * author. Ours live here instead; `drizzle.config.ts` reads both files and
 * `lib/db/client.ts` hands both to Drizzle.
 *
 * Every table keys on `user.id` with `onDelete: "cascade"`. That is not
 * politeness: "delete my account" has to mean it, and
 * `tests/account-cascade.test.mjs` fails if any foreign key in the schema
 * forgets.
 */

/** Preferences that should follow the person, not the browser. */
export const userSettings = pgTable("user_settings", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  // Null means "no choice recorded": follow the browser for locale and the
  // system for theme, which is exactly what a signed-out visitor gets. Storing
  // the absence of a choice as a value would make the account override a
  // preference the person never expressed.
  locale: text("locale"),
  theme: text("theme"),
  // Nothing reads this yet. It is in the design's shape for settings and costs
  // one nullable column now against a migration later.
  oddsFormat: text("odds_format"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

/**
 * Followed teams and competitions.
 *
 * One row per followed thing rather than a JSON blob, so that following
 * Valencia on a phone and Betis on a laptop is a union and not a race between
 * two whole documents — which is what §5 of the design means by "merge, never
 * replace".
 */
export const userFavorites = pgTable(
  "user_favorites",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    value: text("value").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.kind, table.value] }),
    // The client shape is `{teams, competitions}` and nothing else is a
    // favourite; a typo in a route handler should fail loudly here rather than
    // quietly storing a third kind nothing ever reads.
    check("user_favorites_kind", sql`${table.kind} in ('team', 'competition')`),
  ],
);

/**
 * One SquadLab run: a draft, and how it went.
 *
 * A run is reproducible from its inputs — `api/squadlab.py` is seed-driven
 * throughout — so what is stored is the seed, the names and the rerolls, not a
 * season. `result` is stored anyway, and only for this reason: ratings and
 * pools move with the daily refresh, so replaying an old run can produce a
 * different tournament. A finished run therefore keeps its own outcome and the
 * `engineFingerprint` it was played against, and is never silently
 * re-simulated. That is the same reasoning the pre-kickoff prediction log
 * already uses.
 *
 * Keeping every finished run is also what makes gamification possible later
 * without a migration: an award rule like "won the Champions with no card
 * above 80" is a query over these rows, not a replay.
 */
export const squadlabRun = pgTable(
  "squadlab_run",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    mode: text("mode").notNull(),
    // A uint32 from `crypto.getRandomValues`, which overflows int4 above
    // 2,147,483,647 — about half the seeds this would ever be handed.
    seed: bigint("seed", { mode: "number" }).notNull(),
    /** The chosen names, by slot: `{ "GK_0": "Alisson", … }`. */
    squad: jsonb("squad").notNull(),
    /** Rerolls spent per slot, which bound what the draft could have offered. */
    rerolls: jsonb("rerolls").notNull(),
    status: text("status").notNull(),
    /** The `SquadSeason` as played; null while the run is still in progress. */
    result: jsonb("result"),
    /** What the engine looked like when it was played; see lib/engine-fingerprint.ts. */
    engineFingerprint: text("engine_fingerprint"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    // Every read is "this person's runs, newest first".
    index("squadlab_run_user_idx").on(table.userId, table.createdAt),
    check("squadlab_run_mode", sql`${table.mode} in ('draft', 'historic')`),
    check(
      "squadlab_run_status",
      sql`${table.status} in ('in_progress', 'finished')`,
    ),
    // A finished run without its result would be a row that can only lie about
    // what happened, since replaying it may not reproduce it.
    check(
      "squadlab_run_finished_has_result",
      sql`${table.status} <> 'finished' or ${table.result} is not null`,
    ),
  ],
);

/**
 * Gamification, laid out and deliberately empty.
 *
 * The design is explicit that B2 must not invent achievement codes, XP curves
 * or level thresholds — those are a game design, and a different task. What
 * B2 owes them is a place to land that needs no migration when they arrive, so
 * these three tables exist, cascade like everything else, and are written by
 * nothing in this release.
 */
export const userProgress = pgTable("user_progress", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  xp: integer("xp").default(0).notNull(),
  level: integer("level").default(1).notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

/** The catalogue of awards. Seeded by whoever designs them; not user data. */
export const achievement = pgTable("achievement", {
  code: text("code").primaryKey(),
  name: text("name").notNull(),
  description: text("description").notNull(),
  points: integer("points").default(0).notNull(),
});

export const userAchievement = pgTable(
  "user_achievement",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    code: text("code")
      .notNull()
      .references(() => achievement.code, { onDelete: "cascade" }),
    awardedAt: timestamp("awarded_at").defaultNow().notNull(),
  },
  (table) => [primaryKey({ columns: [table.userId, table.code] })],
);
